INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','Discover the recommended broccoli seed rate per hectare, including comprehensive guidance on sowing, spacing, and post-emergence crop management for optimal yields.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'rank_math_focus_keyword','Broccoli Seed Rate per Hectare: Complete Planting and Cultivation Guide' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='rank_math_focus_keyword');
INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Муқаддима: Аҳамияти муайян кардани дақиқи миқдори бодаи шпинат дар ҳектар</h2>\n<p>Шпинат яке аз сабзиҳои маъмул ва дорои арзиши иқтисодии баланд дар Ҷумҳурии Исломии Эрон аст, ки ба нақшагирии дақиқи партоб ниёз дорад. Яке аз мушкилоти асосии деҳқонон, муайян <strong>кардани миқдори бодаи шпинат дар ҳектар</strong> бест. истифодаи нодурусти миқдори бода метавонад боиси зиёд будани рӯёнӣҳо, кам шудани ҳаҷми нодаҳо ва дар натиҷа паст шудани ҳосилнокии меҳват шавад. аз ҷиҳати дигар, кӯҳи камтар аз ҳадди ҷӯроҳат, ҳадди замини заминро аз кор мебардорад ва самаранокии фоидаоварии меҳватро паст мекунад. бинобар ин, дарк кардани тағйирёбандаҳое чун шароитҳои иқлимӣ, намуди хок ва усули обирӣ (қатрӣ ё наҳорӣ) барои ҳисоб кардани дақиқи ин миқдор зарур аст.</p>\n\n<h3>Омилҳои таъсиррасон ба муайян кардани суръати партоб</h3>\n<p>Миқдори бодаи лозима барои ҳар як ҳектар собит нест ва ба омилҳои гуногун вобаста аст. дар ин ҷо ба якчанд параметрҳои асосӣ ишора мекунем:</p>\n<ul>\n<li><strong>Сифат ва қувваи ҷавонафшонии бода:</strong> Бодалҳои тоза бо фоизи баланди ҷавонафшонӣ (90 ва зиёдтар) ба миқдори камтар нисбат ба бодалҳои кӯҳан доранд.</li>\n<li><strong>Фосилаи карсазонии асосӣ ва ҷонибӣ:</strong> Броколи одатан ба фосилаи асосӣ 50 то 60 см ва фосилаи ҷонибӣ 25 то 30 см ниёз дорад. Ин фосилаҳо мустақиман ба шумораи зарраҳо дар ҳектар ва дар охир ба миқдори бӯғдоӣ таъсир мерасонанд.</li>\n<li><strong>Системаи овардан:</strong> Дар системаҳои муосири овардан, идоракунии намӣи хок дақиқтар аст, ки ин метавонад дар шартҳои муайян ба зичии баландтари карсазон оварда расонад.</li>\n</ul>\n\n\n\n<h2>Ҳисобкунии техникӣ: Расидани қадам-ба-қадам ба миқдори бӯғдоии броколи дар ҳектар</h2>\n<p>Барои ҳисобкунии дақиқ <strong>миқдори бӯғдоии броколи дар ҳектар</strong>, мо метавонем аз формулаҳои сода истифода барем, ки дар асоси фосилаҳои карсазон ва фоизи наҷуваранӣ боваранд. Дар ин ҷо мо фарзияи стандартиро дар назар мегирем: фосилаи асосӣ 50 см, фосилаи ҷонибӣ 30 см ва карсазон дар ҳар чунг ё байни онҳо бо 1 то 2 зарра.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/مقدار-بذر-مارچوبه-در-هکتار-راهنمای-جامع-تصویر-شاخص.webp" alt="مقدار بذر مارچوبه در هکتار: راهنمای جامع - تصویر 1"/><figcaption>normasi i bozori sarra dar hektar barod (marichubeh)</figcaption></figure>\n\n<h3>Marhala-i hisob kardani</h3>\n<ol>\n<li><strong>Hisobi shumori navhona\' in dar hektar:</strong> Dar har hektar, agar masofa-i ba\'d 50 cm va masofa-i picho\'ik 30 cm bo\'ad, shumori saf va chashma\'ro hisob mikonem. Az nuqtayi nazari nazari, har 50 sentimitr tarrahi sakhz va har 30 sentimitr tarrahi chashma\'ro 1 yoki 2 navhona\'jo\'ro tayyor mikonad. Bo\' hisobi zarr-i amniyati baroi shikastani navhona\'hon, odatan ba zichii taqriban 33,000 to 40,000 navhona\' dar hektar piro mikonem.</li>\n<li><strong>Vazni buzdori dar har kilogramm:</strong> Vazni 1000 donai marichubeh ba\' mutobiqi buzdor, be\'no 30 to 40 gramm guzoshi mikonad. Ba\' in tarika, dar har kilogramm taqriban 25,000 to 33,333 dona mavjud ast.</li>\n<li><strong>Mosbat karani shumori dona\'ho\' ba\' navhona\'ho\'i zaruri:</strong> Agar farz kunem, har chashma\' ba\' 1.5 dona ehtioj dorasht (ba farzi shikastani ba\'zi navhona\'hon), shumori umumi-i dona\'ho\'i zaruriro ba\' shumori dona dar kilogramm taqsim mikonem, to\' miqdori buzdor\'ro ba kilogramm topem.</li>\n</ol>\n<p>Бо ин ҳисобҳо, миқдори миёнаи бехбарии каймоқ дар ҳактари ғилобиш оддӣ одатан дар густуродаи <strong>1.5 то 2.5 килограмм</strong> паҳн мешавад. Лутфан, диққат диҳед, ки ғилобиши зичтар (бо фосилаи камтар) истемоли бехбиро ба 3 килограмм мебарарад ва ғилобиши камзичтар, онро ба 1 килограмм. Барои муқоиса бо қуттиҳои дигари пиязиҳо, шумо метавонед ба дастурномаро <a href="https://navar-abyari.ir/%d9%85%d9%82%d8%af%d8%a7%d8%b1-%d8%a8%d8%b0%d8%b1-%d8%ac%d8%b9%d9%81%d8%b1%db%8c-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/" target="_blank">миқдори бехбарии чорғунчӣ дар ҳактар</a> ним нигар диҳед, ки асосҳои монанд дорад, вале бо фосилаҳои қат кардан гуногун.</p>\n\n<h2>Таъсири системаҳои ободӣ ба ғилобиши зичият ва истемоли бехбарӣ</h2>\n<p>Интихоби системаи ободӣ танҳо як масъалаи иқтисодӣ нест, балки ба зичи қитъаҳо таъсир мерасонад ва дар натиҷа ба ҳисоб <strong>миқдори бехбарии каймоқ дар ҳактар</strong> таъсир мерасонад. Системаҳои оборӣ бо усули нувори чангҳо ва қаъқумӣ (қатрагӣ) имконияти идоракунии намро фароҳам мекунанд, ки ин барои рушди якхелаи нувори чангҳо муҳим аст.</p>\n\n<h3>Оборӣ бо усули қаъқумӣ (қатрагӣ) ва нувори чангҳо</h3>\n<ul>\n<li><strong>Оборӣ бо усули қаъқумӣ (қатрагӣ):</strong> Имкон медиҳад, ки барои кам кардани рақобати решаҳо масофаҳои вазнин-вазнинтар истифода барем. Вақте ки нам мустақиман ба реша мерасад, ниёз ба ғалладорӣ (карсад) барои истифодаи нурҳои офтоб камтар мегардад. Ин метавонад ба камшавии андозаи нувори чангҳо ва дар натиҷа ба камшавии истифодаи бурсузи дар ҳар гектар кӯмак расонад, аммо дар муқобил, андозаи нувори чангҳоро зиёд мекунад.</li>\n<li><strong>Оборӣ бо усули нувори чангҳо:</strong> Ҳамон мисли усули қаъқумӣ (қатрагӣ) амал мекунад, аммо бо хароҷоти камтар. Муҳим он аст, ки масофаи чангҳоро чунин идора кунед, ки решаҳо дар ҳудуди намакҳо боқӣ монад.</li>\n</ul>\n<p>Дехқонҳо метавонанд тавассути омӯзиши мақолаҳои алоқаманд, аз ҷумла <a href="https://navar-abyari.ir/tarzi-intihobi-tasmai-obyari-nuqtagiri-muvofiq/" target="_blank">нақшаи интихоби системаи мувофиқи обории нувори чангҳо</a>, дар бораи робитани бехтар дар бораи робитани бехтар дар бораи робитани бехтар <a href="https://navar-abyari.ir/%d8%a2%d8%a8%db%8c%d8%a7%d8%b1%db%8c-%d8%a8%d8%a7%d8%b1%d8%a7%d9%86%db%8c-%d8%b2%d9%85%db%8c%d9%86-%da%a9%d8%b4%d8%a7%d9%88%d8%b1%d8%b2%db%8c-%d9%88-%d8%aa%d8%a7%d8%ab%db%8c%d8%b1%d8%a7%d8%aa/" target="_blank">обории до бар замини кишоварзӣ ва таъсири он</a> метавонад нишон диҳад, ки чаро усулҳои навбадкардӣ, назорати беҳтар бар пулҳои рушд ва талаботи бобуҷадӣ фароҳам меорад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/مقدار-بذر-مارچوبه-در-هکتار-راهنمای-جامع-کاربرد-عملی.webp" alt="مقدار بذر مارچوبه در هکتار: راهنمای جامع - تصویر 2"/><figcaption>normaи kormi karpuz bar hectare</figcaption></figure>\n\n\n\n<h2>Nuktai amaliy barои optimizatsiya-и karpuz</h2>\n<p>барои таъмин кардани он, ки <strong>miqdori bobi karbuz dar hektar</strong> барои он ки то боздеии марказӣ оварда шуда, риоя кардани нуқтаҳои зерин зарур аст:</p>\n<ul>\n<li><strong>Тест нарест:</strong> Пеш аз харидани бехҳо, аз як тухми бехҳо санҷиш кунед. Агар нарест паст бошад, миқдори бехҳоро 20 то 30 фоиз зиёд кунед.</li>\n<li><strong>Корпаи арча ва навъи зироат:</strong> Арча набояд пас аз худ арча ё сабзавоти дигари пиёзӣ кӯр кунад. Барои омодагии нави навъи зироатӣ, ба мақолаи «Ҳама чиз дар бораи обгари биологӣ ва принсипҳои кишоварзӣ» диққат диҳед.</li>\n<li><strong>Моделсозии муқоисавӣ:</strong> Агар дар соҳаи сабзавоти дигар фаъолият дошта бошед, муқоисаи суръати ҷо гирифтан метавонад дар муҳосебӣ ба манбаъҳо кӯмак кунад. Баъд, фарқи миқдори бехи лоҷин (баробар ба метр) бо арча таъсири навъи ҷанасса бар зичии нишон медиҳад.</li>\n</ul>\n\n<h2>Ҷавоб ба саволҳои муқаррарӣ (FAQ)</h2>\n\n<h3>1. Оё миқдори бехи арча дар ҷанассаҳои ошёнавӣ бо фазои оғоз якхел аст?</h3>\n<p>Хайр. Дар хонаи шабадонӣ имкон дорад, ки фاصلаро дақиқтар танзим карда, нобудшавиро кам кунед. Одатан зичӣ дар хонаи шабадонӣ баландтар аст, бинобар ин миқдори тоҷнок, ки ҳар метри мурабагӣ истифода мешавад, зиёдтар мебошад. Аммо, зеро сатҳи воҳид хурд аст, ҳисобшавӣ бар асоси гектар метавонад гуногун ба назар расад, вале асоси фавосилҳои насбкунӣ монанд аст.</p>\n\n<h3>2. Чаро тоҷнокҳои булукӣ нархи ҳар килогиро бо ҳам фарқкунанда доранд?</h3>\n<p>Миқдори тоҷноки спаржа дар як гектар ба сифати тоҷнок вобаста аст. Тоҷнокҳои мушаххасшуда ва ба бемониҳо тобовар одатан гаронтар мебошанд, вале фоизи биронии баландтар доранд. Бинобар ин, аз дидгоҳи иқтисодии умумӣ, истифодаи тоҷноки камтар бо сифати баландтар метавонад барои ҳарфишаро аз истифодаи зиёди тоҷноки миёна самараноктар бошад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/مقدار-بذر-مارچوبه-در-هکتار-راهنمای-جامع-جزئیات-فنی.webp" alt="مقدار بذر مارچوبه در هکتار: راهنمای جامع - تصویر 3"/><figcaption>miqdori tojnoke bar gektar bar spargja</figcaption></figure>\n\n<h3>3. Чӣ тавр метавонам пешгирӣ аз пардакунии тоҷнок ҳангоми насбкунӣ равам?</h3>\n<p>Истифодаи насбкунии дастӣ бо риояи дақиқи фавосилҳо ё насби механикушуда бо плантёрҳои танзимшуда, ғарраи тоҷнокро пешгирӣ мекунад. Инчунин, таҳқиқоти хок ва тайёркунии дурусти бедаки насбкунӣ эҳтимоли ҷондани пурраи тоҷнокро дар амики мувофиқ (1 то 1.5 сентиметр) зиёд мекунад.</p>\n\n\n\n<h2>Хулоса: услуб барои ҳалли беҳтар</h2>\n<p>Муайянкунӣ <strong>Миқдори тоқи сабзии бамия дар 1 гектар</strong> Як раванди динамикӣ аст, ки ба тағйирёбандаҳои муҳити зист, биологӣ ва идоракунӣ вобаста аст. Қиматҳои ибтидоӣ аз 1,5 то 2,5 килограмм ҳамчун нуқтаи оғози аъло буда, аммо котиҳон бояд ин рақамҳоро дар асоси натиҷаҳои нақш ва фосилаҳои дақиқи тоқ мутобиқ бақунанд. Нобандӣ бо системаҳои обёрӣи самараноқ, ба монанди муштумарӣ, метавонад ба коҳиши рақобат барои манбаъҳо ва зиёд шудани сифати маҳсул оварда расонад. Бо тадқиқоти манбаъҳои иловагӣ ба монанди <a href="https://navar-abyari.ir/%D9%85%DB%8C%D8%B2%D8%A7%D9%86-%D8%A8%D8%B1%D8%AF%D8%A7%D8%B4%D8%AA-%D9%85%D8%A7%D8%B4-%D8%AF%D8%B1-%D9%87%DA%A9%D8%AA%D8%A7%D8%B1/" target="_blank">Ҳаҷми ҳосили сабзӣ дар 1 гектар</a> ё дигар сабзӣҳо, метавонед тасвири беҳтари идоракунии манбаъҳои боғии худ созед. Дар натиҷа, сабти дақиқи маълумоти ҳар мавсим, калиди беҳтар кардани пайвастаи истифодаи тоқ ва зиёд шудани даромад мебошад.</p>','Miqdori tohuki qalqondon sar zamma: Rahnamai poiyavi borun va parvarish','Дар ин мақола мо миқдори дақиқи истифодаи бӯди чарчӯбӣ дар ҳар гектарро баррасӣ кардем. Амсилҳо, мисли сифати бӯд, усули кӯрконӣ ва системаи обёрӣ ба ин миқдор таъсир мерасонанд. Бо мо ҳамроҳ бошед, то беҳтарин усули кӯрконии чарчӯбиро ёд гиред.','publish','closed','closed','miqdori-tohoki-qalqondon-sar-zamma',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
